int handle_ioctl_sio_cstampns(struct net *net, struct socket *sock, unsigned int cmd, void __user *up)
{
    int ret = -EFAULT;
    struct timespec ts;
    mm_segment_t old_fs = get_fs();

    set_fs(KERNEL_DS);
    ret = sock_do_ioctl(net, sock, cmd, (unsigned long)&ts);
    set_fs(old_fs);

    if (ret < 0)
        return ret;

    if (copy_to_user(up, &ts, sizeof(ts)))
        return -EFAULT;

    return 0;
}
